package com.interviewiq.controller; import com.interviewiq.entity.User; import com.interviewiq.repository.*; import com.interviewiq.security.JwtUtil; import jakarta.validation.constraints.*; import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/auth") public class AuthController { private final UserRepository users; private final PasswordEncoder enc; private final JwtUtil jwt; public AuthController(UserRepository u,PasswordEncoder e,JwtUtil j){users=u;enc=e;jwt=j;} public record Reg(@NotBlank String name,@Email @NotBlank String email,@NotBlank @Size(min=6) String password,String targetRole,String experienceLevel){} public record Log(@Email @NotBlank String email,@NotBlank String password){} private Map<String,Object> tok(User u){ String t=jwt.gen(u.id,u.email,u.role); return Map.of("token",t,"user",Map.of("id",u.id,"name",u.name,"email",u.email,"role",u.role,"targetRole",u.targetRole,"experienceLevel",u.experienceLevel)); } @PostMapping("/register") public ResponseEntity<?> reg(@RequestBody @jakarta.validation.Valid Reg r){ if(users.existsByEmail(r.email())) return ResponseEntity.status(409).body(Map.of("message","Email already registered")); User u=new User(); u.name=r.name(); u.email=r.email().toLowerCase(); u.password=enc.encode(r.password()); if(r.targetRole()!=null) u.targetRole=r.targetRole(); if(r.experienceLevel()!=null) u.experienceLevel=r.experienceLevel(); users.save(u); return ResponseEntity.status(201).body(tok(u)); } @PostMapping("/login") public ResponseEntity<?> login(@RequestBody @jakarta.validation.Valid Log l){ var u=users.findByEmail(l.email().toLowerCase()).orElse(null); if(u==null||!enc.matches(l.password(),u.password)) return ResponseEntity.status(401).body(Map.of("message","Invalid email or password")); return ResponseEntity.ok(tok(u)); } @PostMapping("/logout") public Map<String,String> out(){ return Map.of("message","Logged out"); } }
